198:/** Cellular (Worley) noise: which randomly placed cell `p` falls in, and how far it is from the cell border. */
199:export function cells(p: Vector3, size: number, seed = 0): Cell {
200:  const x = p.x / size;
201:  const y = p.y / size;
202:  const z = p.z / size;
203:  const X = Math.floor(x);
204:  const Y = Math.floor(y);
205:  const Z = Math.floor(z);
206:  let d1 = Infinity;
207:  let d2 = Infinity;
208:  let best = [0, 0, 0];
209:  let bestC = [0, 0, 0];
210:  for (let i = -1; i <= 1; i++)
211:    for (let j = -1; j <= 1; j++)
212:      for (let k = -1; k <= 1; k++) {
213:        const cx = X + i;
214:        const cy = Y + j;
215:        const cz = Z + k;
216:        const px = cx + unit(cx, cy, cz, seed);
217:        const py = cy + unit(cx, cy, cz, seed + 7);
218:        const pz = cz + unit(cx, cy, cz, seed + 13);
219:        const d = Math.hypot(px - x, py - y, pz - z);
220:        if (d < d1) {
221:          d2 = d1;
222:          d1 = d;
223:          best = [cx, cy, cz];
224:          bestC = [px, py, pz];
225:        } else if (d < d2) d2 = d;
226:      }
227:  return {
228:    d1,
229:    d2,
230:    id: unit(best[0], best[1], best[2], seed + 29),
231:    center: new Vector3(bestC[0] * size, bestC[1] * size, bestC[2] * size),
232:  };
233:}
